import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 예산 통제는 프로젝트 금액(project.project_amount)을 한도로 본다.
// 같은 프로젝트에서 이미 상신된 품의 금액(결재대기·승인·완료)에 이번 금액을 더해 한도를 넘으면 상신을 차단한다.
// 프로젝트 금액이 비어 있으면 한도 없음으로 본다.
const COUNTED_STATUSES_NOTE = '결재대기·승인·완료';
// 가정: S3 전자결재 연계는 approval_document 행을 만들어 상신하는 것으로 처리한다.
// 가정: 결재양식은 사용 중인 양식 중 ID가 가장 작은 것을 쓴다.
// 가정: 결재 요청 알림은 기안자에게 포털 채널로 남긴다.
const NOTIFY_CHANNEL = '포털';

@Controller('api/v1')
export class FnSfr03208Controller {
  @Post('/requisitions/:requisitionId/submit')
  @HttpCode(200)
  async submitRequisition(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const requisitionId = req.params['requisitionId'];
    if (typeof requisitionId !== 'string' || !/^[0-9]+$/.test(requisitionId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의서 번호가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT requisition_id AS "requisitionId",
                project_id AS "projectId",
                budget_account_id AS "budgetAccountId",
                drafter_id AS "drafterId",
                title AS "title",
                content AS "content",
                requisition_amount AS "amount",
                status AS "status"
           FROM requisition
          WHERE requisition_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id: requisitionId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'REQUISITION_NOT_FOUND', '품의서를 찾을 수 없습니다.');
      }
      const r = rows[0];
      if (r.status !== '기안') {
        throw new ApiError(409, 'REQUISITION_NOT_EDITABLE', '기안 상태의 품의서만 상신할 수 있습니다.');
      }

      // 예산과목 사용기간 확인
      const accounts = await db.query(
        `SELECT CASE WHEN (use_start_date IS NULL OR use_start_date <= CURRENT_DATE)
                      AND (use_end_date IS NULL OR use_end_date >= CURRENT_DATE)
                    THEN true ELSE false END AS "usable"
           FROM budget_account
          WHERE budget_account_id = CAST(:accountId AS bigint)`,
        { accountId: String(r.budgetAccountId) },
      );
      if (accounts.length === 0) {
        throw new ApiError(409, 'INVALID_STATE', '예산과목을 찾을 수 없어 상신할 수 없습니다.');
      }
      if (accounts[0].usable !== true) {
        throw new ApiError(422, 'BUDGET_CONTROL_EXCEEDED', '예산과목의 사용기간이 아니어서 상신할 수 없습니다.');
      }

      // 예산 통제 확인 (가정: 프로젝트 금액 기준, 대상 상태: ' + COUNTED_STATUSES_NOTE + ')
      const projects = await db.query(
        `SELECT project_amount AS "projectAmount"
           FROM project
          WHERE project_id = CAST(:projectId AS bigint)`,
        { projectId: String(r.projectId) },
      );
      if (projects.length === 0) {
        throw new ApiError(409, 'INVALID_STATE', '프로젝트를 찾을 수 없어 상신할 수 없습니다.');
      }
      const limit = projects[0].projectAmount;
      if (limit !== null && limit !== undefined) {
        const usedRows = await db.query(
          `SELECT COALESCE(SUM(requisition_amount), 0) AS "used"
             FROM requisition
            WHERE project_id = CAST(:projectId AS bigint)
              AND status IN ('결재대기', '승인', '완료')
              AND requisition_id <> CAST(:id AS bigint)`,
          { projectId: String(r.projectId), id: requisitionId },
        );
        const used = Number(usedRows[0].used);
        const total = used + Number(r.amount);
        if (total > Number(limit)) {
          throw new ApiError(
            422,
            'BUDGET_CONTROL_EXCEEDED',
            '품의 금액이 예산 한도를 초과했습니다. 한도 ' + Number(limit) + '원, 사용 예정 ' + total + '원입니다.',
          );
        }
      }

      // 결재양식 선택
      const forms = await db.query(
        `SELECT approval_form_id AS "approvalFormId"
           FROM approval_form
          WHERE use_status = '사용'
          ORDER BY approval_form_id
          LIMIT 1`,
        {},
      );
      if (forms.length === 0) {
        throw new ApiError(409, 'INVALID_STATE', '사용 중인 결재양식이 없어 상신할 수 없습니다.');
      }

      // 전자결재 문서 생성 및 상신
      const docs = await db.query(
        `INSERT INTO approval_document
           (document_no, approval_form_id, drafter_id, title, body, approval_status,
            submitted_at, created_at, updated_at)
         VALUES
           ('REQ-' || :id || '-' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
            CAST(:formId AS bigint), CAST(:drafterId AS bigint), :title, :body, '결재대기',
            now(), now(), now())
         RETURNING approval_document_id AS "approvalDocumentId"`,
        {
          id: requisitionId,
          formId: String(forms[0].approvalFormId),
          drafterId: String(r.drafterId),
          title: r.title,
          body: r.content ?? null,
        },
      );
      const approvalDocumentId = docs[0].approvalDocumentId;

      // 품의서 상태 변경
      const changed = await db.execute(
        `UPDATE requisition
            SET status = '결재대기',
                approval_document_id = CAST(:docId AS bigint),
                updated_at = now()
          WHERE requisition_id = CAST(:id AS bigint)
            AND status = '기안'`,
        { docId: String(approvalDocumentId), id: requisitionId },
      );
      if (changed !== 1) {
        throw new ApiError(409, 'REQUISITION_NOT_EDITABLE', '기안 상태의 품의서만 상신할 수 있습니다.');
      }

      // 결재 요청 알림
      await db.execute(
        `INSERT INTO notification
           (recipient_id, channel, title, content, read_status, event_type,
            target_type, target_id, created_at, updated_at)
         VALUES
           (CAST(:drafterId AS bigint), :channel, :title, :content, '안읽음', 'APPROVAL_REQUEST',
            'APPROVAL_DOCUMENT', CAST(:docId AS bigint), now(), now())`,
        {
          drafterId: String(r.drafterId),
          channel: NOTIFY_CHANNEL,
          title: '결재 요청: ' + r.title,
          content: '품의서가 상신되어 결재 대기 중입니다.',
          docId: String(approvalDocumentId),
        },
      );

      return { status: '결재대기', approvalDocumentId };
    });
  }
}

