import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Select,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['지출', '지출'],
  ['구매', '구매'],
];

export default function FnSfr03208Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 작성·상신한 품의서를 목록으로 보인다.
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [target, setTarget] = useState<Row | null>(null);
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetAccountId, setBudgetAccountId] = useState<number | string>('');
  const [requisitionType, setRequisitionType] = useState('지출');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [amount, setAmount] = useState<number | string>('');

  function resetForm() {
    setProjectId('');
    setBudgetAccountId('');
    setRequisitionType('지출');
    setTitle('');
    setContent('');
    setAmount('');
  }

  async function create() {
    if (projectId === '') throw new Error('프로젝트를 선택해 주세요.');
    if (budgetAccountId === '') throw new Error('예산과목을 선택해 주세요.');
    if (title.trim() === '') throw new Error('품의 제목을 입력해 주세요.');
    if (typeof amount !== 'number' || amount <= 0) throw new Error('품의 금액을 0보다 큰 숫자로 입력해 주세요.');
    const res = await call('POST', '/requisitions', role, {
      projectId,
      budgetAccountId,
      requisitionType,
      title: title.trim(),
      content,
      requisitionAmount: amount,
    });
    const row: Row = {
      requisitionId: res['requisitionId'],
      projectId,
      budgetAccountId,
      requisitionType,
      title: title.trim(),
      requisitionAmount: amount,
      status: res['status'],
    };
    setRows([row, ...rows]);
    setCreating(false);
    resetForm();
    notify('품의서를 저장했습니다.');
  }

  async function submit() {
    if (!target) return;
    const res = await call('POST', '/requisitions/' + String(target['requisitionId']) + '/submit', role, {});
    setRows(
      rows.map((r) =>
        r['requisitionId'] === target['requisitionId']
          ? { ...r, status: res['status'], approvalDocumentId: res['approvalDocumentId'] }
          : r,
      ),
    );
    setTarget(null);
    notify('품의서를 상신했습니다.');
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>지출품의서</h2>
        <Band total={rows.length}>
          <button onClick={() => setCreating(true)}>품의서 작성</button>
        </Band>
        <DataTable
          columns={[
            { key: 'requisitionId', label: '품의서 ID' },
            { key: 'title', label: '품의 제목' },
            { key: 'requisitionAmount', label: '품의 금액', render: (r) => <Num value={r['requisitionAmount']} /> },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['status'] === '기안' ? (
                  <button
                    className="ghost"
                    onClick={(e) => {
                      e.stopPropagation();
                      setTarget(r);
                    }}
                  >
                    상신
                  </button>
                ) : null,
            },
          ]}
          rows={rows}
          empty="아직 작성한 품의서가 없습니다. 품의서 작성 버튼으로 시작해 주세요."
        />
      </section>
      {creating && (
        <Drawer
          title="품의서 작성"
          onClose={() => {
            setCreating(false);
          }}
        >
          <Form onSubmit={create} submit="저장">
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_account" role={role} value={budgetAccountId} onChange={setBudgetAccountId} />
            </Field>
            <Field label="품의 유형" required>
              <Select value={requisitionType} onChange={setRequisitionType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="품의 제목" required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="품의 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label="품의 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {target && (
        <Drawer title="품의서 상신" onClose={() => setTarget(null)}>
          <Form
            onSubmit={submit}
            submit="상신"
            note={<span>상신하면 전자결재가 시작되고 상태가 결재대기로 바뀌며, 기안 상태로 되돌릴 수 없습니다.</span>}
          >
            <Field label="품의 제목">
              <span>{String(target['title'])}</span>
            </Field>
            <Field label="품의 금액">
              <Num value={target['requisitionAmount']} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
